package sem

import (
	"reflect"
	"testing"
)

func conditionalReturnFlow(name string) returnFlowCall {
	return returnFlowCall{
		Name:         name,
		Reason:       "callee return value returned through conditional expression",
		EvidenceKind: "conditional_return_flow",
		Detail:       name,
		Direction:    "callee_to_caller",
	}
}

func fallbackReturnFlow(name string) returnFlowCall {
	return returnFlowCall{
		Name:         name,
		Reason:       "callee return value returned through fallback expression",
		EvidenceKind: "fallback_return_flow",
		Detail:       name,
		Direction:    "callee_to_caller",
	}
}

func TestPunctuationPrefilteredReturnFlowsPreserveConditionalAndFallbackResults(t *testing.T) {
	tests := []struct {
		name  string
		kind  string
		block string
		want  []returnFlowCall
	}{
		{
			name: "ternary with tabs and nested arguments",
			kind: "conditional",
			block: "\treturn condition\t?\tprimary(inner(arg, other)) :\t" +
				"fallback(other(arg))\n",
			want: []returnFlowCall{conditionalReturnFlow("fallback"), conditionalReturnFlow("primary")},
		},
		{
			name:  "or fallback with nested arguments",
			kind:  "fallback",
			block: "return primary(inner(arg, other)) || fallback(other(arg))\n",
			want:  []returnFlowCall{fallbackReturnFlow("fallback"), fallbackReturnFlow("primary")},
		},
		{
			name:  "null-coalescing fallback with nested arguments",
			kind:  "fallback",
			block: "return primary(inner(arg, other)) ?? fallback(other(arg))\n",
			want:  []returnFlowCall{fallbackReturnFlow("fallback"), fallbackReturnFlow("primary")},
		},
		{
			name:  "Python if fallback with tabs",
			kind:  "conditional",
			block: "return primary(inner(arg))\tif\tcondition\telse\tfallback(other(arg))\n",
			want:  []returnFlowCall{conditionalReturnFlow("fallback"), conditionalReturnFlow("primary")},
		},
		{
			name:  "Python or fallback with tabs",
			kind:  "fallback",
			block: "return primary(inner(arg))\tor\tfallback(other(arg))\n",
			want:  []returnFlowCall{fallbackReturnFlow("fallback"), fallbackReturnFlow("primary")},
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			var got []returnFlowCall
			switch tt.kind {
			case "conditional":
				got = ternaryReturnFlows(tt.block)
			case "fallback":
				got = fallbackReturnFlows(tt.block)
			default:
				t.Fatalf("unknown flow kind %q", tt.kind)
			}
			if !reflect.DeepEqual(got, tt.want) {
				t.Fatalf("return-flow result = %#v, want %#v", got, tt.want)
			}
		})
	}
}

func TestPunctuationPrefilteredReturnFlowsSkipAbsentTriggerFamilies(t *testing.T) {
	block := "return direct(inner(arg, other))\n"
	if got := ternaryReturnFlows(block); got != nil {
		t.Fatalf("ternary flows for body without '?' = %#v, want nil", got)
	}
	if got := fallbackReturnFlows(block); got != nil {
		t.Fatalf("fallback flows for body without fallback operator = %#v, want nil", got)
	}

	got := returnFlowCalls(newSymbolBody(block), nil)
	want := []returnFlowCall{{
		Name:         "direct",
		Reason:       "callee return value flows into caller return value",
		EvidenceKind: "return_flow",
		Detail:       "direct",
		Direction:    "callee_to_caller",
	}}
	if !reflect.DeepEqual(got, want) {
		t.Fatalf("unconditional return flow = %#v, want %#v", got, want)
	}
}

func TestPunctuationPrefilteredAssignmentFlowsKeepOrderingAndDeduplication(t *testing.T) {
	tests := []struct {
		name  string
		block string
		want  []returnFlowCall
	}{
		{
			name: "ternary assignment",
			block: "value = condition\t?\tprimary(inner(arg))\t:\t" +
				"fallback(other(arg))\nreturn value\n",
			want: []returnFlowCall{
				fallbackReturnFlow("fallback"),
				conditionalReturnFlow("primary"),
			},
		},
		{
			name:  "Python if assignment with tabs",
			block: "value = primary(inner(arg))\tif\tcondition\telse\tfallback(other(arg))\nreturn value\n",
			want: []returnFlowCall{
				fallbackReturnFlow("fallback"),
				conditionalReturnFlow("primary"),
			},
		},
		{
			name:  "or assignment",
			block: "value = primary(inner(arg)) || fallback(other(arg))\nreturn value\n",
			want:  []returnFlowCall{fallbackReturnFlow("fallback"), fallbackReturnFlow("primary")},
		},
		{
			name:  "Python or assignment with tabs",
			block: "value = primary(inner(arg))\tor\tfallback(other(arg))\nreturn value\n",
			want:  []returnFlowCall{fallbackReturnFlow("fallback"), fallbackReturnFlow("primary")},
		},
		{
			name:  "null-coalescing assignment repeated",
			block: "value = primary(inner(arg)) ?? fallback(other(arg))\nreturn value\nreturn value\n",
			want:  []returnFlowCall{fallbackReturnFlow("fallback"), fallbackReturnFlow("primary")},
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			got := returnFlowCalls(newSymbolBody(tt.block), nil)
			if !reflect.DeepEqual(got, tt.want) {
				t.Fatalf("returnFlowCalls() = %#v, want %#v", got, tt.want)
			}
		})
	}
}

