package sem

import (
	"os"
	"strings"
	"testing"
)

func TestChargedNestedIgnoreReusesFrozenPolicyAfterMutation(t *testing.T) {
	for _, test := range []struct {
		name   string
		mutate func(*testing.T, string)
	}{
		{name: "removed", mutate: func(t *testing.T, repo string) {
			if err := os.Remove(repo + "/sub/.gitignore"); err != nil {
				t.Fatal(err)
			}
		}},
		{name: "replaced", mutate: func(t *testing.T, repo string) {
			write(t, repo, "sub/.gitignore", "replacement.go\n")
		}},
	} {
		t.Run(test.name, func(t *testing.T) {
			repo := t.TempDir()
			const frozen = "frozen.go\n"
			write(t, repo, "sub/.gitignore", frozen)
			store := newCapturedStore(t.Context(), nil, -1)
			t.Cleanup(func() { _ = store.close() })
			base := ignoreMatcher{capture: store, captureRepo: repo}

			first := newNestedIgnoreStack(repo, base)
			ok, err := first.enterCharged(nil, "sub")
			_ = first.close()
			if err != nil || !ok {
				t.Fatalf("initial capture: ok=%t err=%v", ok, err)
			}
			test.mutate(t, repo)

			ledger := &repoIgnoreLedger{}
			second := newNestedIgnoreStack(repo, base)
			defer second.close()
			ok, err = second.enterCharged(ledger, "sub")
			if err != nil || !ok {
				t.Fatalf("charged replay: ok=%t err=%v", ok, err)
			}
			if !second.Ignored("sub/frozen.go", false) {
				t.Fatal("charged replay dropped the frozen nested-ignore rule")
			}
			if second.Ignored("sub/replacement.go", false) {
				t.Fatal("charged replay observed replacement policy bytes")
			}
			if ledger.ignoreBytesRead != int64(len(frozen)) {
				t.Fatalf("charged replay accounted %d ignore bytes, want %d", ledger.ignoreBytesRead, len(frozen))
			}
		})
	}
}

func TestChargedNestedIgnoreRefusalDoesNotPublishCapturedAbsence(t *testing.T) {
	repo := t.TempDir()
	write(t, repo, "sub/.gitignore", strings.Repeat("x", maxNestedIgnoreFileBytes+1))
	store := newCapturedStore(t.Context(), nil, -1)
	t.Cleanup(func() { _ = store.close() })
	base := ignoreMatcher{capture: store, captureRepo: repo}

	ledger := &repoIgnoreLedger{}
	charged := newNestedIgnoreStack(repo, base)
	ok, err := charged.enterCharged(ledger, "sub")
	_ = charged.close()
	if err != nil || ok {
		t.Fatalf("oversized charged policy: ok=%t err=%v, want a bounded refusal", ok, err)
	}

	write(t, repo, "sub/.gitignore", "admitted.go\n")
	ordinary := newNestedIgnoreStack(repo, base)
	defer ordinary.close()
	ok, err = ordinary.enterCharged(nil, "sub")
	if err != nil || !ok {
		t.Fatalf("ordinary read after refusal: ok=%t err=%v", ok, err)
	}
	if !ordinary.Ignored("sub/admitted.go", false) {
		t.Fatal("charged refusal was cached as absence and hid the later admissible policy")
	}
}

