// captureMatchStream observes a descriptor without retaining the file. The
// caller reduces emitted substrings to query-term presence, so storage is
// independent of source length and the number of matches on one long line.
type captureMatchStream struct {
	ctx             context.Context
	matcher         *regexp.Regexp
	emit            func(string)
	emitLine        func(string)
	window          int
	buffer          string
	line            string
	lines, maxLines int
	lineMatched     bool
	matched         bool
	sniffed         int
	binary          bool
}

func newCaptureMatchStream(ctx context.Context, patterns []string, maxLines int, emit func(string)) (*captureMatchStream, error) {
	locale := ""
	for _, name := range []string{"LC_ALL", "LC_CTYPE", "LANG"} {
		if locale = os.Getenv(name); locale != "" {
			break
		}
	}
	asciiFold := locale == "" || locale == "C" || locale == "POSIX"
	quoted := make([]string, 0, len(patterns))
	window := 1
	for _, pattern := range patterns {
		if pattern == "" {
			continue
		}
		quotedPattern := regexp.QuoteMeta(pattern)
		if asciiFold {
			var fixed strings.Builder
			for _, character := range pattern {
				if character >= 'A' && character <= 'Z' {
					character += 'a' - 'A'
				}
				if character >= 'a' && character <= 'z' {
					fixed.WriteRune('[')
					fixed.WriteRune(character)
					fixed.WriteRune(character - 'a' + 'A')
					fixed.WriteRune(']')
				} else {
					fixed.WriteString(regexp.QuoteMeta(string(character)))
				}
			}
			quotedPattern = fixed.String()
		}
		quoted = append(quoted, quotedPattern)
		// Case folding can change UTF-8 width. Four bytes per rune bounds
		// every spelling accepted by the fixed-string regular expression.
		window = max(window, utf8.RuneCountInString(pattern)*utf8.UTFMax)
	}
	expression := "(?:" + strings.Join(quoted, "|") + ")"
	if !asciiFold {
		expression = "(?i)" + expression
	}
	matcher, err := regexp.Compile(expression)
	if err != nil {
		return nil, err
	}
	matcher.Longest()
	if maxLines <= 0 {
		maxLines = 32
	}
	stream := &captureMatchStream{ctx: ctx, matcher: matcher, emit: emit, window: window, maxLines: maxLines}
	if len(quoted) == 0 {
		stream.lines = maxLines
	}
	return stream, nil
}

// newCapturePatternStream applies the same caller-built expressions as the
// alias-aware Git preselection path. The expressions already encode case and
// token-boundary policy, so they must not be quoted as fixed strings here.
func newCapturePatternStream(ctx context.Context, patterns []string, maxLines int, emit func(string)) (*captureMatchStream, error) {
	if len(patterns) == 0 {
		return &captureMatchStream{ctx: ctx, emit: emit, lines: maxLines, maxLines: maxLines}, nil
	}
	expression := "(?:" + strings.Join(patterns, "|") + ")"
	matcher, err := regexp.Compile(expression)
	if err != nil {
		return nil, err
	}
	matcher.Longest()
	if maxLines <= 0 {
		maxLines = 32
	}
	window := 1
	for _, pattern := range patterns {
		window = max(window, utf8.RuneCountInString(pattern)*utf8.UTFMax)
	}
	return &captureMatchStream{ctx: ctx, matcher: matcher, emit: emit, window: window, maxLines: maxLines}, nil
}

func (stream *captureMatchStream) Write(data []byte) (int, error) {
	count := len(data)
	if stream.sniffed < 8000 {
		prefix := data[:min(len(data), 8000-stream.sniffed)]
		stream.binary = stream.binary || bytes.IndexByte(prefix, 0) >= 0
		stream.sniffed += len(prefix)
	}
	for len(data) > 0 {
		if err := stream.ctx.Err(); err != nil {
			return count - len(data), err
		}
		if stream.lines >= stream.maxLines {
			return count, nil
		}
		part := data[:min(len(data), 32<<10)]
		data = data[len(part):]
		for len(part) > 0 {
			end := bytes.IndexByte(part, '\n')
			if end < 0 {
				if stream.emitLine != nil {
					stream.line += string(part)
				}
				stream.buffer += string(part)
				stream.drain(false)
				break
			}
			if stream.emitLine != nil {
				stream.line += string(part[:end])
			}
			stream.buffer += string(part[:end])
"}

