func (writer *captureSearchPassWriter) Write(data []byte) (int, error) {
	count := len(data)
	for len(data) > 0 {
		end := bytes.IndexByte(data, '\n')
		if end < 0 {
			if err := writer.appendLine(data); err != nil {
				return count - len(data), err
			}
			break
		}
		if err := writer.appendLine(data[:end]); err != nil {
			return count - len(data), err
		}
		if err := writer.finishLine(false); err != nil {
			return count - len(data), err
		}
		data = data[end+1:]
	}
	return count, nil
}

func (writer *captureSearchPassWriter) appendLine(data []byte) error {
	if len(data) > writer.maxLine-writer.line.Len() {
		return fmt.Errorf("captured preselection line exceeds operation input limit %d bytes", writer.maxLine)
	}
	_, _ = writer.line.Write(data)
	return nil
}

func (writer *captureSearchPassWriter) finishLine(final bool) error {
	line := writer.line.String()
	for index := range writer.matched {
		writer.matched[index] = false
	}
	for _, stream := range writer.streams {
		if _, err := stream.Write([]byte(line)); err != nil {
			return err
		}
		if final {
			if err := stream.finish(); err != nil {
				return err
			}
		} else if _, err := stream.Write([]byte{'\n'}); err != nil {
			return err
		}
	}
	any := false
	for _, matched := range writer.matched {
		any = any || matched
	}
	if any {
		terms := writer.queryMatcher.match(line)
		lower := strings.ToLower(line)
		for index, matched := range writer.matched {
			if !matched {
				continue
			}
			for termIndex, termMatched := range terms {
				writer.evidence[index].terms[termIndex] = writer.evidence[index].terms[termIndex] || termMatched
			}
			if len(writer.passes[index].aliases) > 0 {
				confirmed := false
				for _, alias := range writer.passes[index].aliases {
					confirmed = confirmed || searchQueryTermMatches(writer.query, line, lower, alias)
				}
				writer.evidence[index].needsValidation = writer.evidence[index].needsValidation || !confirmed
			}
		}
	}
	writer.line.Reset()
	return nil
}

