+func TestExtractionRecordPreservesCPlusPlusOutOfLineResolution(t *testing.T) {
+	fixtures := []struct{ path, content string }{
+		{"ledger.hpp", "namespace api { class Ledger { public: int Add(int value); }; }\n"},
+		{"ledger.cpp", "int api::Ledger::Add(int value) { return value; }\n"},
+	}
+	cache := &extractionCache{
+		ctx: context.Background(), directory: t.TempDir(), repository: "fixture/repo", build: "fixture-build",
+		maxBytes: extractionDiskLimit, maxEntries: extractionEntryLimit, limitsReady: true,
+	}
+	extract := func(wantHit bool) []fileExtraction {
+		out := make([]fileExtraction, 0, len(fixtures))
+		for _, fixture := range fixtures {
+			language, ok := languageForContent(fixture.path, fixture.content)
+			if !ok {
+				t.Fatalf("C++ language unavailable for %s", fixture.path)
+			}
+			got, hit := cache.extract(resolveProfile(ProfileFull), language, captureSource(fixture.path, fixture.content), defaultMaxParseBytes)
+			if hit != wantHit {
+				t.Fatalf("cache hit for %s = %v, want %v", fixture.path, hit, wantHit)
+			}
+			out = append(out, got)
+		}
+		cache.flush()
+		return out
+	}
+	resolve := func(extractions []fileExtraction) SymbolRecord {
+		var symbols []SymbolRecord
+		for index, extraction := range extractions {
+			symbols = append(symbols, entitySymbols("fixture", fixtures[index].path, extraction.language, extraction.entities)...)
+		}
+		var declaration SymbolRecord
+		for _, symbol := range symbols {
+			if symbol.Name == "Add" && symbol.bodyless {
+				declaration = symbol
+				break
+			}
+		}
+		if declaration.ID == "" || len(declaration.cPlusPlusOwners) == 0 {
+			t.Fatalf("extraction lost C++ declaration owners: %#v", declaration)
+		}
+		definition, ok := cPlusPlusOutOfLineDefinition(declaration, symbols)
+		if !ok || definition.FilePath != "ledger.cpp" || definition.cPlusPlusDefinitionName == "" {
